/// Two dependent loads, matching the shape of `properties.record`.
pub fn wordProperties(cp: u21) WordProperties {
    if (cp >= 0x110000) return word_default;
    const block = word_index[cp >> word_block_shift];
    const offset = (@as(usize, block) << word_block_shift) | (cp & (@as(usize, 1) << word_block_shift) - 1);
    return @bitCast(word_data[offset]);
}
